create or replace function public.depurnrfi_d_grant_user_authorization(p_run_id text,p_stage text,p_user_message_hash text,p_allowed_object_id text default null,p_metadata jsonb default '{}'::jsonb) returns uuid language plpgsql security definer set search_path=public,extensions as $$ declare r public.depurnrfi_d_runs%rowtype; aid uuid; begin select * into r from public.depurnrfi_d_runs where run_id=p_run_id; if not found then raise exception 'DEPURNRFI_D_AUTH_RUN_NOT_FOUND'; end if; if p_stage not in ('DEPURATION_D_DIALOGUE_TURN','DEPURATION_D_CLOSING') then raise exception 'DEPURNRFI_D_AUTH_STAGE_INVALID'; end if; if r.pre_dialogue_frozen<>true or r.status not in ('WAITING_USER_AUTHORIZATION','DIALOGUE_ACTIVE') then raise exception 'DEPURNRFI_D_AUTH_PRE_DIALOGUE_FREEZE_REQUIRED status=%',r.status; end if; if coalesce(trim(p_user_message_hash),'')='' then raise exception 'DEPURNRFI_D_USER_MESSAGE_HASH_REQUIRED'; end if; perform set_config('kendel.user_auth_commit','on',true); insert into public.kendel_user_authorizations(canonical_agent_id,internal_agent_id,mission_id,stage,user_message_hash,source,allowed_object_id,metadata) values('@AnalistaDepuracionRNFI_D','@AnalistaDepuracionRNFI_D',p_run_id,p_stage,p_user_message_hash,'CHAT_USER_EXPLICIT',p_allowed_object_id,coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('explicit_user_authorization',true,'user_mediated',true,'one_intervention_only',true)) returning authorization_id into aid; perform set_config('kendel.user_auth_commit','off',true); return aid; end $$;

create or replace function public.depurnrfi_d_commit_dialogue_turn_authorized(p_authorization_id uuid,p_run_id text,p_inbound_actor text,p_inbound_text text,p_outbound_text text,p_topics jsonb default '[]'::jsonb,p_evidence_refs jsonb default '[]'::jsonb) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare r public.depurnrfi_d_runs%rowtype; n integer; tid uuid; new_ver integer; begin select * into r from public.depurnrfi_d_runs where run_id=p_run_id for update; if not found then raise exception 'DEPURNRFI_D_RUN_NOT_FOUND'; end if; if not r.pre_dialogue_frozen or r.status not in ('WAITING_USER_AUTHORIZATION','DIALOGUE_ACTIVE') then raise exception 'DEPURNRFI_D_DIALOGUE_NOT_AVAILABLE status=%',r.status; end if; if p_inbound_actor not in ('ANALISTA_DEPURACION_NRFI_A','USER_TRANSPORTED_A_MESSAGE','USER') then raise exception 'DEPURNRFI_D_DIALOGUE_INBOUND_ACTOR_INVALID'; end if; if length(trim(coalesce(p_inbound_text,'')))<1 or length(trim(coalesce(p_outbound_text,'')))<1 then raise exception 'DEPURNRFI_D_COMPLETE_INBOUND_AND_OUTBOUND_REQUIRED'; end if; perform public.kendel_consume_user_authorization(p_authorization_id,'@AnalistaDepuracionRNFI_D',p_run_id,'DEPURATION_D_DIALOGUE_TURN','depurnrfi_d_commit_dialogue_turn',null); select coalesce(max(turn_number),0)+1 into n from public.depurnrfi_d_dialogue_turns where run_id=p_run_id; perform set_config('depurnrfi_d.kernel_commit','on',true); insert into public.depurnrfi_d_dialogue_turns(run_id,turn_number,authorization_id,inbound_actor,inbound_text,outbound_text,topics,evidence_refs,inbound_hash,outbound_hash) values(p_run_id,n,p_authorization_id,p_inbound_actor,p_inbound_text,p_outbound_text,coalesce(p_topics,'[]'::jsonb),coalesce(p_evidence_refs,'[]'::jsonb),public.depurnrfi_d_text_hash(p_inbound_text),public.depurnrfi_d_text_hash(p_outbound_text)) returning turn_id into tid; new_ver=r.state_version+1; update public.depurnrfi_d_runs set status='WAITING_USER_AUTHORIZATION',state_version=new_ver,updated_at=clock_timestamp() where run_id=p_run_id; perform public.depurnrfi_d_append_event(p_run_id,'DIALOGUE','DIALOGUE_TURN_COMMITTED',new_ver,jsonb_build_object('turn_id',tid,'turn_number',n,'authorization_id',p_authorization_id,'next_state','STOP_WAITING_USER_AUTHORIZATION','auto_continue',false)); perform set_config('depurnrfi_d.kernel_commit','off',true); return jsonb_build_object('turn_id',tid,'turn_number',n,'chat_payload',p_outbound_text,'next_state','STOP_WAITING_USER_AUTHORIZATION','auto_continue',false); end $$;

create or replace function public.depurnrfi_d_commit_dialogue_closing_authorized(p_authorization_id uuid,p_run_id text,p_artifact_id text,p_closing_payload jsonb) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare r public.depurnrfi_d_runs%rowtype; n integer; cid uuid; h text; chat text; new_ver integer; begin select * into r from public.depurnrfi_d_runs where run_id=p_run_id for update; if not found then raise exception 'DEPURNRFI_D_RUN_NOT_FOUND'; end if; if not r.pre_dialogue_frozen or r.status<>'WAITING_USER_AUTHORIZATION' then raise exception 'DEPURNRFI_D_CLOSING_NOT_AVAILABLE status=%',r.status; end if; select count(*) into n from public.depurnrfi_d_dialogue_turns where run_id=p_run_id; if n<1 then raise exception 'DEPURNRFI_D_AT_LEAST_ONE_DIALOGUE_TURN_REQUIRED'; end if; if p_closing_payload is null or jsonb_typeof(p_closing_payload)<>'object' then raise exception 'DEPURNRFI_D_CLOSING_OBJECT_REQUIRED'; end if; if not (p_closing_payload ? 'agreement_status' and p_closing_payload ? 'final_d_position' and p_closing_payload ? 'handoff_to_a' and p_closing_payload ? 'chat_payload') then raise exception 'DEPURNRFI_D_CLOSING_REQUIRED_SECTION_MISSING'; end if; chat=coalesce(p_closing_payload->>'chat_payload',''); if length(trim(chat))<20 then raise exception 'DEPURNRFI_D_CLOSING_CHAT_PAYLOAD_REQUIRED'; end if; perform public.kendel_consume_user_authorization(p_authorization_id,'@AnalistaDepuracionRNFI_D',p_run_id,'DEPURATION_D_CLOSING','depurnrfi_d_commit_dialogue_closing',null); h=public.depurnrfi_d_jsonb_hash(p_closing_payload); perform set_config('depurnrfi_d.kernel_commit','on',true); insert into public.depurnrfi_d_dialogue_closings(run_id,authorization_id,artifact_id,closing_payload,closing_hash) values(p_run_id,p_authorization_id,p_artifact_id,p_closing_payload,h) returning closing_id into cid; new_ver=r.state_version+1; update public.depurnrfi_d_runs set status='D_DIALOGUE_PARTICIPATION_COMPLETE',phase_cursor='D_TERMINATED',state_version=new_ver,updated_at=clock_timestamp(),completed_at=clock_timestamp() where run_id=p_run_id; perform public.depurnrfi_d_append_event(p_run_id,'DIALOGUE','D_DIALOGUE_CLOSING_COMMITTED',new_ver,jsonb_build_object('closing_id',cid,'closing_hash',h,'d_terminates_first',true,'a_closes_system',true)); perform set_config('depurnrfi_d.kernel_commit','off',true); return jsonb_build_object('closing_id',cid,'closing_hash',h,'chat_payload',chat,'next_state','D_DIALOGUE_PARTICIPATION_COMPLETE_STOP','auto_continue',false,'a_closes_system',true); end $$;

revoke all on function public.depurnrfi_d_grant_user_authorization(text,text,text,text,jsonb) from public,anon,authenticated; revoke all on function public.depurnrfi_d_commit_dialogue_turn_authorized(uuid,text,text,text,text,jsonb,jsonb) from public,anon,authenticated; revoke all on function public.depurnrfi_d_commit_dialogue_closing_authorized(uuid,text,text,jsonb) from public,anon,authenticated;
grant execute on function public.depurnrfi_d_grant_user_authorization(text,text,text,text,jsonb) to service_role; grant execute on function public.depurnrfi_d_commit_dialogue_turn_authorized(uuid,text,text,text,text,jsonb,jsonb) to service_role; grant execute on function public.depurnrfi_d_commit_dialogue_closing_authorized(uuid,text,text,jsonb) to service_role;

insert into public.kendel_agent_catalog(menu_order,canonical_agent_id,display_name,internal_agent_id,current_version,role,scope,factual_source,output_destination,drive_folder_id,mother_doc_id,kernel_edge_slug,audit_enabled,expected_contract,metadata,updated_at) values(4,'@AnalistaDepuracionRNFI_D','AnalistaDepuracionRNFI. D','@AnalistaDepuracionRNFI_D','ANALISTADEPURACIONRNFI-D-AGENT-1.0','CAUSAL_NRFI_SLATE_DEPURATOR_D','FULL_MLB_SLATE','Factual slate packets / validated source objects; targeted factual recovery only through authorized research path','MAX_4_DEEP_ANALYSIS_CANDIDATE_DOSSIERS + FINAL_DEPURATION_REPORT_D + D_DIALOGUE_CLOSING_REPORT','1WItLWad07tx1QyODDu-nq_XLmAqRWLH4','1ZsPlc2tOSzRH4_XQB0IpzwLGTQxeGASsjy8Cbzy3HLM','analista-depuracion-nrfi-d-kernel',true,jsonb_build_object('phase_order',jsonb_build_array('F1','F2','F3','F4','F5','F6','F7','F8','F9','D1','D2','F10','F11','REPORT_D','PRE_DIALOGUE_FREEZE','DIALOGUE'),'full_slate',true,'candidate_max',4,'candidate_is_pick',false,'betting_authority',false,'auto_continuous_pre_dialogue',true,'manual_dialogue_authorization',true,'one_authorization_per_d_response',true,'auto_chain_dialogue',false,'complete_chat_turn_required',true,'d_closes_first',true,'a_closes_system',true),jsonb_build_object('source_sha256','121f80c4569de1f87c438f96fbd48364a1756afee17a38f3f1f33698a67caea9','source_requirements',1057),clock_timestamp()) on conflict(canonical_agent_id) do update set menu_order=excluded.menu_order,display_name=excluded.display_name,internal_agent_id=excluded.internal_agent_id,current_version=excluded.current_version,role=excluded.role,scope=excluded.scope,factual_source=excluded.factual_source,output_destination=excluded.output_destination,drive_folder_id=excluded.drive_folder_id,mother_doc_id=excluded.mother_doc_id,kernel_edge_slug=excluded.kernel_edge_slug,audit_enabled=true,expected_contract=excluded.expected_contract,metadata=excluded.metadata,updated_at=clock_timestamp();
